def max_distinct_sum(N, A):
    distinct_counts = [set() for _ in range(N)]
    distinct_counts[0].add(A[0])

    for i in range(1, N):
        distinct_counts[i] = distinct_counts[i-1]
        if A[i] not in distinct_counts[i]:
            distinct_counts[i].add(A[i])

    return max(len(distinct_counts[i]) + len(distinct_counts[j]) for i in range(N-1) for j in range(i+1))

