def max_distinct_counts(N, A):
    distinct_counts = [0] * (N + 1)
    for i in range(1, N + 1):
        distinct_counts[i] = distinct_counts[i - 1]
        if A[i - 1] not in distinct_counts:
            distinct_counts[A[i - 1]] += 1

    prefix_sum = [0] * (N + 1)
    for i in range(1, N + 1):
        prefix_sum[i] = prefix_sum[i - 1] + distinct_counts[i]

    max_sum = 0
    for i in range(1, N):
        max_sum = max(max_sum, prefix_sum[i])

    return max_sum

