def max_distinct_counts(N, A):
    distinct_counts = [1] * N
    max_sum = 0

    for i in range(1, N):
        if A[i] != A[i - 1]:
            distinct_counts[i] += distinct_counts[i - 1]

    for i in range(N - 1):
        max_sum = max(max_sum, distinct_counts[i])

    return max_sum

