class Solution:
    def maximumAmount(self, coins: List[List[int]]) -> int:
        m, n = len(coins), len(coins[0])

        # Initialize the DP table
        dp = [[0] * n for _ in range(m)]

        # Base case: start position
        dp[0][0] = coins[0][0]

        # Fill the first row
        for j in range(1, n):
            dp[0][j] = dp[0][j-1] + coins[0][j]

        # Fill the first column
        for i in range(1, m):
            dp[i][0] = dp[i-1][0] + coins[i][0]

        # Fill the rest of the DP table
        for i in range(1, m):
            for j in range(1, n):
                # Choose the maximum between moving right or moving down
                if coins[i][j] >= 0:
                    dp[i][j] = max(dp[i-1][j], dp[i][j-1]) + coins[i][j]
                else:
                    # If encountering a robber, consider two neutralizations
                    dp[i][j] = max(
                        dp[i-1][j] + coins[i][j],
                        dp[i][j-1] + coins[i][j],
                        dp[i-2][j] + coins[i][j],
                        dp[i-2][j-1] + coins[i][j]
                    )

        return dp[m-1][n-1]

