class Solution:
    def maximumAmount(self, coins: List[List[int]]) -> int:
        m, n = len(coins), len(coins[0])

        # Initialize DP table
        dp = [[0] * n for _ in range(m)]

        # Base case: starting position
        dp[0][0] = coins[0][0]

        # Fill DP table
        for i in range(1, m):
            dp[i][0] = dp[i-1][0] + coins[i][0]
        for j in range(1, n):
            dp[0][j] = dp[0][j-1] + coins[0][j]

        for i in range(1, m):
            for j in range(1, n):
                # Calculate the maximum profit for each cell
                left = dp[i-1][j] if i > 0 else float('-inf')
                up = dp[i][j-1] if j > 0 else float('-inf')

                # Neutralize robbers if possible
                if i > 1 and coins[i-2][j] >= 0:
                    left += coins[i-2][j]
                if j > 1 and coins[i][j-2] >= 0:
                    up += coins[i][j-2]

                dp[i][j] = max(left, up) + coins[i][j]

        return dp[m-1][n-1]

