class Solution:
    def maxFreeTime(self, eventTime: int, k: int, startTime: List[int], endTime: List[int]) -> int:
        # Sort the meetings based on start time
        events = sorted(zip(startTime, endTime))

        # Initialize variables
        free_time = 0
        current_free_time = 0

        for start, end in events:
            # If there are more than k overlapping meetings, find the one with the smallest end time
            if current_free_time + eventTime > end:
                if k > 0:
                    k -= 1
                    current_free_time = end
                else:
                    break
            # Update the current free time
            current_free_time = max(current_free_time, end)

        return free_time

class Solution:
    def maxFreeTime(self, eventTime: int, k: int, startTime: List[int], endTime: List[int]) -> int:
        # Sort the meetings based on start times
        sorted_meetings = sorted(zip(startTime, endTime))

        # Initialize variables to keep track of the current end time and the maximum free time
        current_end_time = 0
        max_free_time = 0

        # Iterate through the sorted meetings
        for start, end in sorted_meetings:
            # If the current meeting starts before or at the end of the current free time, update the current end time
            if start > current_end_time:
                current_end_time = end
            else:
                # Otherwise, we have a conflict, so we need to find the longest free time available
                # We check if there's enough time left to accommodate the new meeting without exceeding the event time
                if current_end_time + eventTime >= start:
                    # If there is, we can adjust the current end time to the end of the new meeting
                    current_end_time = end
                else:
                    # If not, we cannot accommodate the new meeting, so we return the maximum free time found so far
                    return max_free_time

        # If we finish iterating through all meetings, we have found the maximum free time
        return max_free_time

