class Solution:
    def maxFreeTime(self, eventTime: int, k: int, startTime: List[int], endTime: List[int]) -> int:
        # Sort the meetings based on their start times
        sorted_meetings = sorted(zip(startTime, endTime))

        # Initialize variables for tracking the current meeting's end time and the maximum free time
        current_end_time = 0
        max_free_time = 0

        # Iterate through the sorted meetings
        for start, end in sorted_meetings:
            # If the current meeting starts before the previous meeting ends, update the current meeting's end time
            if start < current_end_time:
                current_end_time = min(current_end_time, end)
            else:
                # Otherwise, calculate the free time and update the maximum free time if necessary
                free_time = current_end_time - start
                if k > 0:
                    k -= 1
                    current_end_time = end
                else:
                    return max(max_free_time, free_time)

        # Return the maximum free time after processing all meetings
        return max(max_free_time, current_end_time - start)

