class Solution:
    def minimumPairRemoval(self, nums: List[int]) -> int:
        n = len(nums)
        dp = [[float('inf')] * (n + 1) for _ in range(n + 1)]
        dp[0][0] = 0

        for i in range(1, n + 1):
            for j in range(i + 1):
                if j == 0:
                    dp[i][j] = min(dp[i - 1][j], abs(nums[i - 1]))
                else:
                    dp[i][j] = min(dp[i - 1][j], dp[i - 1][j - 1] + abs(nums[i - 1] - nums[j - 1]))

        return dp[n][n]

