class Solution:
    def minimumPairRemoval(self, nums: List[int]) -> int:
        n = len(nums)
        dp = [[float('inf')] * n for _ in range(n)]

        # Base case: single element arrays are considered non-decreasing
        for i in range(n):
            dp[i][i] = 0

        # Fill the DP table
        for length in range(2, n + 1):
            for start in range(n - length + 1):
                end = start + length - 1
                min_sum = float('inf')

                # Find the minimum sum of adjacent elements in the current subarray
                for mid in range(start, end):
                    min_sum = min(min_sum, nums[mid])

                # Update the DP table
                for mid in range(start, end):
                    dp[start][end] = min(dp[start][end], dp[start][mid] + dp[mid + 1][end])

        return dp[0][n - 1]

