class Solution:
    def minimumPairRemoval(self, nums: List[int]) -> int:
        # Sort the array to make it non-decreasing
        nums.sort()
        # Calculate the difference between each element and the next one
        differences = [nums[i+1] - nums[i] for i in range(len(nums)-1)]
        # Sum up the absolute values of these differences to get the total cost
        return sum(abs(diff) for diff in differences)

