class Solution:
    def minimumPairRemoval(self, nums: List[int]) -> int:
        n = len(nums)
        dp = [[float('inf')] * n for _ in range(n)]

        # Base case: The minimum cost to make a single element non-decreasing is 0
        for i in range(n):
            dp[i][i] = 0

        # Fill the dp table
        for length in range(2, n + 1):
            for start in range(n - length + 1):
                end = start + length - 1
                min_cost = float('inf')

                # Try replacing each pair (start, end)
                for mid in range(start, end):
                    min_cost = min(min_cost, dp[start][mid] + dp[mid + 1][end])

                # Update the dp table
                dp[start][end] = min_cost

        return dp[0][-1]

