class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        # Initialize two dictionaries to store counts of numbers
        count = Counter(nums)
        even_count = Counter()
        odd_count = Counter()

        # Count occurrences of even and odd numbers in each subarray of size k
        for i in range(len(nums)):
            if i < k:
                if nums[i] % 2 == 0:
                    even_count[nums[i]] += 1
                else:
                    odd_count[nums[i]] += 1
            elif i >= k:
                if nums[i] % 2 == 0:
                    even_count[nums[i-k]] -= 1
                else:
                    odd_count[nums[i-k]] -= 1
                if nums[i] % 2 == 0:
                    even_count[nums[i]] += 1
                else:
                    odd_count[nums[i]] += 1

        # Find the largest number that appears in exactly one subarray of size k
        max_num = -1
        for num in nums:
            if num % 2 == 0 and even_count[num] == 1 or num % 2 != 0 and odd_count[num] == 1:
                max_num = max(max_num, num)

        return max_num

