    def largestInteger(self, nums: List[int], k: int) -> int:
        # Dictionary to store counts of each number
        count_map = {}

        # Count occurrences of each number
        for num in nums:
            if num not in count_map:
                count_map[num] = 0
            count_map[num] += 1

        # Sort numbers based on their frequency and value
        sorted_nums = sorted(count_map.items(), key=lambda x: (-x[1], -x[0]))

        # Initialize variables to track the result and the current subarray length
        result = -1
        current_length = 0

        # Iterate through the sorted list
        for num, freq in sorted_nums:
            # Check if adding the current number to the current subarray would exceed the required length
            if current_length + freq > k:
                break

            # Add the current number to the current subarray
            current_length += freq
            result = max(result, num)

        return result

