    count = [0] * (N + 1)
    for num in A:
        count[num] += 1

    # Initialize variables to keep track of adjacent counts
    left_count = 0
    right_count = 0

    # Calculate adjacent counts
    for i in range(1, N + 1):
        if count[i] > 1:
            if count[i - 1] == 0:
                left_count += count[i]
            else:
                right_count += count[i]

    # Calculate the number of valid pairs
    total_pairs = 0
    for i in range(1, N + 1):
        if count[i] > 1:
            if count[i - 1] == 0:
                total_pairs += left_count * (count[i] - 1) // 2
            else:
                total_pairs += right_count * (count[i] - 1) // 2

    return total_pairs

